// src/components/CorpusManager.jsx
import { useState, useEffect } from "react";
import { api } from "../api/client";

const LANG_OPTIONS = ["en", "hi", "ta", "fr", "de", "es", "zh", "ar"];
const MODALITY_OPTIONS = ["text", "image", "audio"];

export default function CorpusManager({ onClose, onCorpusChange }) {
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [addForm, setAddForm] = useState({ content: "", source: "", lang: "en", modality: "text", provenance_score: 0.85 });
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    fetchCorpus();
  }, []);

  async function fetchCorpus() {
    setLoading(true);
    try {
      const data = await api.getCorpus();
      setDocs(data.documents);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }

  async function handleAdd(e) {
    e.preventDefault();
    if (!addForm.content.trim()) return;
    setAdding(true);
    try {
      await api.addDocument(addForm);
      await fetchCorpus();
      setAddForm({ content: "", source: "", lang: "en", modality: "text", provenance_score: 0.85 });
      onCorpusChange();
    } catch (err) {
      setError(err.message);
    } finally {
      setAdding(false);
    }
  }

  async function handleRemove(id) {
    try {
      await api.removeDocument(id);
      await fetchCorpus();
      onCorpusChange();
    } catch (err) {
      setError(err.message);
    }
  }

  async function handleReset() {
    try {
      await api.resetCorpus();
      await fetchCorpus();
      onCorpusChange();
    } catch (err) {
      setError(err.message);
    }
  }

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <span className="modal-title">Corpus Manager</span>
          <span className="modal-badge">{docs.length} docs</span>
          <button className="modal-close" onClick={onClose}>✕</button>
        </div>

        {error && <div className="modal-error">{error}</div>}

        {/* Add form */}
        <form className="add-form" onSubmit={handleAdd}>
          <div className="form-label">Add Document</div>
          <textarea
            className="form-textarea"
            placeholder="Document content…"
            value={addForm.content}
            onChange={e => setAddForm(f => ({ ...f, content: e.target.value }))}
            rows={3}
          />
          <div className="form-row">
            <input
              className="form-input"
              placeholder="source (e.g. dgca_gov_in)"
              value={addForm.source}
              onChange={e => setAddForm(f => ({ ...f, source: e.target.value }))}
            />
            <select className="form-select" value={addForm.lang} onChange={e => setAddForm(f => ({ ...f, lang: e.target.value }))}>
              {LANG_OPTIONS.map(l => <option key={l}>{l}</option>)}
            </select>
            <select className="form-select" value={addForm.modality} onChange={e => setAddForm(f => ({ ...f, modality: e.target.value }))}>
              {MODALITY_OPTIONS.map(m => <option key={m}>{m}</option>)}
            </select>
            <input
              className="form-input narrow"
              type="number" step="0.01" min="0" max="1"
              placeholder="prov"
              value={addForm.provenance_score}
              onChange={e => setAddForm(f => ({ ...f, provenance_score: parseFloat(e.target.value) }))}
            />
            <button className="form-submit" type="submit" disabled={adding}>
              {adding ? "…" : "+ Add"}
            </button>
          </div>
        </form>

        {/* Doc list */}
        <div className="doc-list">
          {loading ? (
            <div className="modal-empty">Loading…</div>
          ) : docs.length === 0 ? (
            <div className="modal-empty">No documents in corpus.</div>
          ) : (
            docs.map((doc, i) => (
              <div className="doc-row" key={i}>
                <div className="doc-meta">
                  <span className="doc-tag">{doc.modality}</span>
                  <span className="doc-tag doc-tag-lang">{doc.lang}</span>
                  <span className="doc-source">{doc.source || "—"}</span>
                  <span className="doc-prov">prov {doc.provenance_score?.toFixed(2)}</span>
                </div>
                <div className="doc-content">{String(doc.content).slice(0, 120)}{doc.content?.length > 120 ? "…" : ""}</div>
                <button className="doc-remove" onClick={() => handleRemove(i)} title="Remove">✕</button>
              </div>
            ))
          )}
        </div>

        <div className="modal-footer">
          <button className="btn-reset" onClick={handleReset}>↺ Reset to Demo Corpus</button>
        </div>
      </div>
    </div>
  );
}
